#pragma once

#include <juce_core/juce_core.h>

// Instrument-preset model (presets/<vendor>/*.json, generated by tools/ot_docs).
// Note numbers follow the Yamaha / Orchestral Tools convention: C3 = MIDI 60.

namespace tp
{
constexpr int kMiddleCOctave = 3;

juce::String noteName (int midiNote);
int parseNoteName (const juce::String& name); // -1 on failure

enum class Category { shortNote, longNote, dynamic, phrase };
juce::String toString (Category);
Category categoryFromString (const juce::String&);

enum class DynamicsSource { velocity, cc1, autoDetect };
juce::String toString (DynamicsSource);

struct NoteRange { int lo = 0, hi = -1; };

struct Articulation
{
    int index = 0;              // 1-based position in SINE's articulation list -> keyswitch slot
    juce::var docNumber;        // number printed in the docs (may differ / be missing)
    juce::String name;
    Category category = Category::shortNote;
    bool legato = false;
    juce::Array<NoteRange> ranges;
    juce::StringArray dynamics; // e.g. {"pp","mf","ff"}
    int roundRobins = 1;
    int keyswitch = -1;         // explicit keyswitch note (players without a keyswitch grid, e.g. Kontakt); -1 = base + index - 1
    juce::StringArray issues;

    juce::Array<int> allNotes() const;
    juce::String rangeText() const;
};

// "C2-C6, D7" (note names or MIDI numbers) -> ranges; false if any part does not parse
bool parseRangeText (const juce::String&, juce::Array<NoteRange>& out);

struct Instrument
{
    juce::String name, group;
    std::vector<Articulation> articulations;
    juce::String displayName() const { return group.isNotEmpty() && group != name ? group + " / " + name : name; }
};

struct Collection
{
    juce::String vendor, name, player, source;
    juce::String keyswitchBase; // e.g. "C0" - default key of articulation #1, empty if unknown
    juce::File file;
    std::vector<Instrument> instruments;

    static juce::Result load (const juce::File&, Collection& out);
    juce::Result save (const juce::File&) const; // secant.preset JSON (the format load() reads)
};

} // namespace tp
